module majority (
    input a, b, c,
    output out
);
    wire not_a, notb, notc;
    wire term_ab, term_bc, term_ac;
    wire or_term1, term_or1;

    not (not_a, a);
    not (notb, b);
    not (notc, c);

    and (term_ab, a, b);
    and (term_bc, b, c);
    and (term_ac, a, c);

    or (or_term1, term_ab, term_bc);
    and (term_or1, or_term1, notc);

    or (out, term_or1, term_ac);
endmodule

