module fsm_3state (
    input clk, reset,
    output [1:0] state
);

// Define state parameters
localparam [1:0] R = 2'b00,
                 Y = 2'b01,
                 B = 2'b10;

reg [1:0] current_state;

assign state = current_state;

always @(posedge clk) begin
    if (reset) begin
        current_state <= R;
