module traffic_light (
    input clk, reset,
    output [2:0] light
);

localparam RED    = 2'b00,
           GREEN  = 2'b01,
           YELLOW = 2'b10;

reg [1:0] current_state, next_state;

// State transition
always @(posedge clk) begin
    if (reset)
        current_state <= RED;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        RED:    next_state = GREEN;
        GREEN:  next_state = YELLOW;
        YELLOW: next_state = RED;
        default: next_state = RED;
    endcase
end

// Output logic
assign light = (current_state == RED)    ? 3'b100 :
               (current_state == GREEN)  ? 3'b010 :
               (current_state == YELLOW) ? 3'b001 : 3'b100;

endmodule

module traffic_light (
