// Next state logic (combinational)
always @(*) begin
    case (current_state)
        NG:   next_state = HY;
        HY:   next_state = FG;
        FG:   next_state = FG_W;
        FG_W: next_state = NG;
        default: next_state = NG;
    endcase
end

// Output logic (combinational)
always @(*) begin
    case (current_state)
        NG:   light = 3'b001;
        HY:   light = 3'b010;
        FG:   light = 3'b100;
        FG_W: light = 3'b100;
        default: light = 3'b001;
    endcase
end

