module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

localparam [1:0] Floor0 = 2'd0,
                 Floor1 = 2'd1,
                 Floor2 = 2'd2;

reg [1:0] current_state, next_state;

assign state = current_state;

always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= Floor0;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        Floor0: next_state = up_request ? Floor1 : Floor0;
        Floor1: begin
            if (up_request)
                next_state = Floor2;
            else if (down_request)
                next_state = Floor0;
            else
                next_state = Floor1;
        end
        Floor2: next_state = down_request ? Floor1 : Floor2;
        default: next_state = Floor0;
    endcase
end

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // Define states
    localparam [1:0] S0 = 2'b00,
                     S1 = 2'b01,
                     S2 = 2'b10;

    reg [1:0] state_reg, state_next;

    // Sequential block for state transitions
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= S0;
        end else begin
            state_reg <= state_next;
        end
    end

    // Combinational block for next state
    always @(*) begin
        case (state_reg)
            S0: begin
                if (up_request)
                    state_next = S1;
                else if (down_request)
                    state_next = S2;
                else
                    state_next = S0;
            end
            S1: begin
                if (up_request)
                    state_next = S1;
                else
                    state_next = S0;
            end
            S2: begin
                if (down_request)
                    state_next = S2;
                else
                    state_next = S0;
            end
            default: state_next = S0;
        endcase
    end

    assign state = state_reg;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State definitions
    localparam [1:0] Ground  = 2'b00,
                     Floor1  = 2'b01,
                     Floor2  = 2'b10;

    reg [1:0] current_state, next_state;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= Ground;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            Ground: begin
                if (up_request) begin
                    next_state = Floor1;
                end else if (down_request) begin
                    next_state = Floor2;
                end else begin
                    next_state = Ground;
                end
            end
            Floor1: begin
                if (up_request) begin
                    next_state = Floor2;
                end else if (down_request) begin
                    next_state = Ground;
                end else begin
                    next_state = Floor1;
                end
            end
            Floor2: begin
                if (down_request) begin
                    next_state = Floor1;
                end else if (up_request) begin
                    next_state = Floor1;
                end else begin
                    next_state = Floor2;
                end
            end
            default: next_state = Ground;
        endcase
    end

    // Output current state
    assign state = current_state;

endmodule

