module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // Define state parameters
    localparam S_ROOM   = 2'b00;
    localparam S_FLOOR  = 2'b01;
    localparam S_MOVE   = 2'b10;

    reg [1:0] state_reg, state_next;

    // State register
    always @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= S_ROOM;
        else
            state_reg <= state_next;
    end

    // Next state logic
    always @(*) begin
        case (state_reg)
            S_ROOM: begin
                if (up_request)
                    state_next = S_MOVE;
                else if (down_request)
                    state_next = S_MOVE;
                else
                    state_next = S_ROOM;
            end
            S_MOVE: begin
                if (up_request)
                    state_next = S_FLOOR;
                else if (down_request)
                    state_next = S_ROOM;
                else
                    state_next = S_ROOM;
            end
            S_FLOOR: begin
                if (up_request)
                    state_next = S_ROOM;
                else if (down_request)
                    state_next = S_ROOM;
                else
                    state_next = S_ROOM;
            end
            default: state_next = S_ROOM;
        endcase
    end

    // Output logic
    assign state = state_reg;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    localparam IDLE   = 2'b00,
               S5     = 2'b01,
               VEND   = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        case (current_state)
            IDLE: begin
                if (coin_inserted) begin
                    next_state = S5;
                end else if (item_selected) begin
                    next_state = VEND;
                end else begin
                    next_state = IDLE;
                end
            end
            S5: begin
                if (coin_inserted) begin
                    next_state = VEND;
                end else if (item_selected) begin
                    next_state = VEND;
                end else begin
                    next_state = S5;
                end
            end
            VEND: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    localparam NO_ST,
               s5,
               s10;

    reg [1:0] current_state, next_state;

    assign state = current_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= NO_ST;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        if (reset) begin
            next_state = NO_ST;
        end else begin
            case (current_state)
                NO_ST: begin
                    if (item_selected) begin
                        next_state = s10;
                    end else if (coin_inserted) begin
                        next_state = s5;
                    end else begin
                        next_state = NO_ST;
                    end
                end
                s5: begin
                    if (item_selected || coin_inserted) begin
                        next_state = s10;
                    end else begin
                        next_state = s5;
                    end
                end
                s10: begin
                    next_state = s10;
                end
                default: next_state = NO_ST;
            endcase
        end
    end

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

localparam [1:0] s0 = 2'b00,
                 s1 = 2'b01,
                 s2 = 2'b10;

reg [1:0] current_state, next_state;

// State register
always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= s0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        s0: next_state = (coin_inserted) ? s1 : s0;
        s1: begin
            if (item_selected)
                next_state = (coin_inserted) ? s2 : s1;
            else
                next_state = (coin_inserted) ? s2 : s1;
        end
        s2: next_state = (item_selected) ? s0 : s2;
