module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

parameter IDLE      = 2'b00,
          S5C_STATE = 2'b01,
          PRODUCT   = 2'b10;

reg [1:0] current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end

always @(*) begin
    case (current_state)
        IDLE: begin
            if (coin_inserted) begin
                next_state = S5C_STATE;
            end else if (item_selected) begin
                next_state = PRODUCT;
            end else begin
                next_state = IDLE;
            end
        end
        S5C_STATE: begin
            if (coin_inserted) begin
                next_state = PRODUCT;
            end else if (item_selected) begin
                next_state = PRODUCT;
            end else begin
                next_state = S5C_STATE;
            end
        end
        PRODUCT: begin
            next_state = IDLE;
        end
        default: begin
            next_state = IDLE;
        end
    endcase
end

assign state = current_state;

endmodule

