    wire [15:0] magnitude = in_0[15] ? -in_0 : in_0; // Compute magnitude based on sign
    wire [4:0] integer_bits = magnitude[15:1]; // Count leading '1's in upper 15 bits

    // Determine if value is a power of two (exactly one '1' in upper 15 bits)
    wire is_power_two = ( (in_0[15:1] ^ (in_0[15] ? 15'b11111 : 15'b0) ) == 15'b1000000000000000 );

    // Calculate exponent (bits -1), convert to 8-bit fixed-point
    reg [7:0] exp;
    integer [4:0] bits_minus_one;
