    wire [3:0] rotated_D_in = {D_in[3], D_in[3:1]};    // Rotate left by 1 for D_in[3:1]

    wire [3:0] D_out = E_in ^ (rotated_E_in & KEY);
    wire [3:0] E_out = D_in ^ (rotated_D_in & KEY);

    assign data_out = {D_out, E_out};
endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [3:0] left_in = data_in[7:4];
    wire [3:0] right_in = data_in[3:0];
    wire [3:0] rotated_left = {left_in[1:0], left_in[3:2]};
    wire [3:0] rotated_right = {right_in[1:0], right_in[3:2]};

    wire [3:0] effective_key = KEY ^ {4{data_in[7]}};

    wire [3:0] l0, l1, l2, l3;
    wire [3:0] r0, r1, r2, r3;

    // Compute left-hand outputs using AND and XOR operations
    assign l0 = (left_in[3] & rotated_left[2]) ^ rotated_left[1];
    assign l1 = (left_in[2] ^ rotated_left[3]) & rotated_left[0];
    assign l2 = (left_in[1] & rotated_left[2]) ^ rotated_left[3];
    assign l3 = (left_in[0] ^ rotated_left[1]) | rotated_left[0];

    // Compute right-hand outputs using AND and XOR operations
    assign r0 = (right_in[3] & rotated_right[2]) ^ rotated_right[1];
    assign r1 = (right_in[2] ^ rotated_right[3]) & rotated_right[0];
    assign r2 = (right_in[1] & rotated_right[2]) ^ rotated_right[3];
    assign r3 = (right_in[0] ^ rotated_right[1]) | rotated_right[0];

    // Combine outputs with l0 and r0 as MSBs, lowest bit from l3|r3
    assign data_out = {l0[3], l0[2:1], r0[3], r0[2:1], l3[0], r3[0]};

endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010;
    wire [3:0] D_in = data_in[7:4];
    wire [3:0] E_in = data_in[3:0];
    wire [3:0] rotated_key = {KEY[0], KEY[3:1]}; // Rotate left once for intermediate key

    // Compute intermediate signals
    wire [3:0] c1, c2, c3, c4;
    assign c1 = (D_in ^ rotated_key) & E_in;
    assign c2 = (D_in ^ rotated_key) | E_in;
    assign c3 = (D_in ^ rotated_key) ^ E_in;
    assign c4 = (D_in ^ rotated_key) ^ ~E_in;

    // Invert the intermediate signals (assumed using ~c2 and ~c4 due to problem's ambiguity)
    wire [3:0] c2_inv = ~c2;
    wire [3:0] c4_inv = ~c4;

    // Concatenate inverted intermediates and add 1
    wire [7:0] concat = {c1_inv, c2_inv, c3_inv, c4_inv};
    assign data_out = concat + 8'd1;
endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [3:0] D0 = data_in[3:0];
    wire [3:0] D1 = data_in[7:4];
    wire [3:0] E0 = D1 ^ (KEY & 4'hF);
    wire [3:0] D2 = D0 ^ E0;
    wire [3:0] D3 = D1;
    wire [3:0] E1 = D3 ^ (KEY & 4'hF);
    wire [3:0] D4 = D2 ^ E1;
    wire [3:0] D5 = D3;
    wire [3:0] E2 = D5 ^ (KEY & 4'hF);
    wire [3:0] D6 = D4 ^ E2;
    wire [3:0] D7 = D5;
    wire [3:0] E3 = D7 ^ (KEY & 4'hF);

    assign data_out = {E3, D6, E2, D4, E1, D2, E0, D0};
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);

localparam counter_width = 1 + $clog2(1); // Calculate width needed for initial 1-cycle reset

reg [counter_width-1:0] counter_reg;
wire [counter_width-1:0] next_counter;

// Counter logic with synchronous reset
always @(posedge clk) begin
    if (rst)
        counter_reg <= {counter_width{1'b0}};
    else
        counter_reg <= next_counter;
end

// Next counter value assignment
assign next_counter = (counter_reg == 1) ? 0 : counter_reg + 1;

// Output is the LSB of the counter
assign clk_out = counter_reg[0];

endmodule

