module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] eq_bit;
    wire [3:0] eq_xor;
    wire and3_out, and2_out, and1_out, and0_out;
    wire [3:0] and_out;
    wire nand4_out, nand3_out, nand2_out, nand1_out, nand0_out;
    wire [3:0] nand_out;
    wire not_nand4, not_nand3, not_nand2, not_nand1, not_nand0;
    wire [3:0] not_nand_out;

    // Generate eq_xor (a XOR b using NAND gates)
    genvar i;
    generate
        for (i=0; i<4; i=i+1) begin: xor_bits
            wire nand1, nand2, nand3;
            nand(nand1, a[i], b[i]);
            nand(nand2, a[i], nand1);
            nand(nand3, b[i], nand1);
            nand(eq_xor[i], nand2, nand3);
        end
    endgenerate

    // Generate eq_bit (equality using NAND and invert)
    generate
        for (i=0; i<4; i=i+1) begin: eq_bit_and
            nand(and_out, eq_xor[i], eq_xor[i]);
            not(eq_bit[i], and_out);
        end
    endgenerate

    // Generate gt (a > b)
    generate
        for (i=0; i<4; i=i+1) begin: gt_nand
            nand(nand_out[i], a[i], and_out[i]);
            nand(gt_nand_nand, nand_out[i], nand_out[i]);
            not(gt_nand[i], gt_nand_nand);
        end
    endgenerate

    // Generate eq (all bits equal)
    generate
        nand(nand_eq, eq_bit[3], eq_bit[2], eq_bit[1], eq_bit[0]);
        not(eq, nand_eq);
    endgenerate

    // Generate lt (a < b)
    generate
        not(not_nand4, and_out[3]);
        not(not_nand3, and_out[2]);
        not(not_nand2, and_out[1]);
        not(not_nand1, and_out[0]);
        not(not_nand0, and_out[0]);
        generate
            for (i=0; i<4; i=i+1) begin: lt_nand
                if (i == 0) begin
                    wire nand_lt;
                    nand(nand_lt, not_nand4, not_nand0);
                    not(lt_nand[i], nand_lt);
                end else begin
                    wire [2:0] and_chain;
                    and(and_chain[0], not_nand4, not_nand(i[3:1]));
                    and(and_chain[1], and_chain[0], and_out[i[2:1]]);
                    and(and_chain[2], and_chain[1], and_out[i[1:0]]);
                    not(lt_nand[i], and_chain[2]);
                end
            end
        endgenerate
    endgenerate
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [1:0] count;
    assign count = a[3] + a[2] + a[1] + a[0];
    assign gt = (count > 1);
    assign eq = (count == 1);
    assign lt = a[3];
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] a_and ~b;
    wire [3:0] b_and ~a;
    wire [3:0] and_terms;
    wire [3:0] or_terms;

    // Compute a AND ~b for each bit using XNOR implemented as AND with 1ns delay
    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : and_xor
            and #(1,1) and_gate(a_and[i], a[i], ~b[i]);
            not #(1,1) not_gate(b_and[i], b_and[i], a_and[i]);
            and #(1,1) and_term1(and_terms[0], a_and[i], b_and[i]);
            and #(1,1) and_term2(or_terms[0], a[i], ~b[i]);
            and #(1,1) and_term1(and_terms[1], a_and[1], b_and[1]);
            and #(1,1) and_term2(or_terms[1], a[1], ~b[1]);
            and #(1,1) and_term1(and_terms[2], a_and[2], b_and[2]);
            and #(1,1) and_term2(or_terms[2], a[2], ~b[2]);
            and #(1,1) and_term1(and_terms[3], a_and[3], b_and[3]);
            and #(1,1) and_term2(or_terms[3], a[3], ~b[3]);
        end
    endgenerate

    // Combine AND terms using OR gates with 1ns delay
    or #(1,1) or_gate(gt, and_terms[3], and_terms[2], and_terms[1], and_terms[0]);
    or #(1,1) or_gate(eq, and_terms[0], and_terms[1], and_terms[2], and_terms[3]);
    or #(1,1) or_gate(or_terms, or_terms[3], or_terms[2], or_terms[1], or_terms[0]);

    // Invert the OR terms for lt using NOT gates with 1ns delay
    not #(1,1) not_ltg (lt, or_terms[3], or_terms[2], or_terms[1], or_terms[0]);
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] eq_bit;
    wire [3:0] term_gt, term_lt;

    assign eq_bit[3] = (a[3] == b[3]);
    assign term_gt[3] = a[3] & ~b[3];
    assign term_lt[3] = ~a[3] & b[3];

    assign eq_bit[2] = (a[2] == b[2]);
    assign term_gt[2] = eq_bit[3] & term_gt[2];
    assign term_lt[2] = eq_bit[3] & term_lt[2];

    assign eq_bit[1] = (a[1] == b[1]);
    assign term_gt[1] = eq_bit[2] & term_gt[1];
    assign term_lt[1] = eq_bit[2] & term_lt[1];

    assign eq_bit[0] = (a[0] == b[0]);
    assign term_gt[0] = eq_bit[1] & term_gt[0];
    assign term_lt[0] = eq_bit[1] & term_lt[0];

    assign eq = &eq_bit;
    assign gt = term_gt[3] | (term_gt[2] & eq_bit[3]) | (term_gt[1] & eq_bit[3] & eq_bit[2]) | (term_gt[0] & eq_bit[3] & eq_bit[2] & eq_bit[1]);
    assign lt = term_lt[3] | (term_lt[2] & eq_bit[3]) | (term_lt[1] & eq_bit[3] & eq_bit[2]) | (term_lt[0] & eq_bit[3] & eq_bit[2] & eq_bit[1]);
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] eq_bit;
    wire [3:0] and1, and2;
    wire [3:0] or1, or2;
    wire all_eq;

    // Compute equality for each bit using XNOR implemented with allowed gates
    assign eq_bit[0] = ~(a[0] ~^ a[0]);  // a[0] XNOR a[0] = 1
    assign eq_bit[1] = ~(a[1] ~^ a[1]);  // a[1] XNOR a[1] = 1
    assign eq_bit[2] = ~(a[2] ~^ a[2]);  // a[2] XNOR a[2] = 1
    assign eq_bit[3] = ~(a[3] ~^ a[3]);  // a[3] XNOR a[3] = 1

    // Check if all bits are equal
    and #1 (all_eq, &eq_bit);            // AND all eq_bit signals

    // Generate a > b using AND/OR/NOT (assumes a and b are complements)
    wire [3:0] a_and_nota;
    wire [3:0] b_and_nota;
    wire [3:0] or_terms;

    genvar i;
    generate
        for (i=0; i<4; i=i+1) begin: comp_or
            and #1 a1 (a_and_nota, a[i], ~b[i]);
            and #1 a2 (b_and_nota, b[i], ~a[i]);
            or #1 o1 (or_terms, a_and_nota, b_and_nota);
        end
    endgenerate

    not #1 n1 (a_gt_b, all_eq);
    and #1 a3 (gt, a_gt_b, all_eq);

    not #1 n2 (lt, a_gt_b);
    or #1 o2 (eq, a_gt_b, lt);

endmodule

