module decoder3to8(input [2:0] in, input enable, output [7:0] out;

    wire not_in2, not_in1, not_in0;
    wire term0, term1, term2, term3, term4, term5, term6, term7;

    // Invert each input bit using NAND gates
    nand (not_in2, in[2], in[2]);
    nand (not_in1, in[1], in[1]);
    nand (not_in0, in[0], in[0]);

    // Generate each AND term with 1ns delay
    nand (term0, not_in2, not_in1, not_in0);
    nand (term1, not_in2, not_in1, in[0]);
    nand (term2, not_in2, in[1], not_in0);
    nand (term3, not_in2, in[1], in[0]);
    nand (term4, in[2], not_in1, not_in0);
    nand (term5, in[2], not_in1, in[0]);
    nand (term6, in[2], in[1], not_in0);
    nand (term7, in[2], in[1], in[0]);

    // Combine terms with enable using NAND and invert to get AND results
    nand (out[0], enable, term0);
    nand (out[1], enable, term1);
    nand (out[2], enable, term2);
    nand (out[3], enable, term3);
    nand (out[4], enable, term4);
    nand (out[5], enable, term5);
    nand (out[6], enable, term6);
    nand (out[7], enable, term7);

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out;

    wire not_en, not_in0, not_in1, not_in2;

    // Invert enable and input bits using NAND gates
    nand(not_en, enable, enable);  // not_en = ~enable
    nand(not_in0, in[0], in[0]);   // not_in0 = ~in[0]
    nand(not_in1, in[1], in[1]);   // not_in1 = ~in[1]
    nand(not_in2, in[2], in[2]);   // not_in2 = ~in[2]

    // Generate each output using three-input NAND of enable, selects, and inverted inputs
    nand(out[0], enable, not_in2, not_in1, not_in0);
    nand(out[1], enable, not_in2, not_in1, in[0]);
    nand(out[2], enable, not_in2, in[1], not_in0);
    nand(out[3], enable, not_in2, in[1], in[0]);
    nand(out[4], enable, in[2], not_in1, not_in0);
    nand(out[5], enable, in[2], not_in1, in[0]);
    nand(out[6], enable, in[2], in[1], not_in0);
    nand(out[7], enable, in[2], in[1], in[0]);

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out;
    parameter DELAY = 1;

    wire enable_n;
    not #(DELAY) not_enable (enable_n, enable);

    wire [2:0] in_delayed;
    and #(DELAY) and0 (in_delayed[2], in[2], enable_n);
    and #(DELAY) and1 (out[0], in_delayed[2], in[1], in[0]);
    and #(DELAY) and2 (in_delayed[1], in[1], enable_n);
    and #(DELAY) and3 (out[1], in_delayed[1], in[0]);
    and #(DELAY) and4 (in_delayed[0], in[0], enable_n);
    and #(DELAY) and5 (out[2], in_delayed[0], in[0]);

    wire [7:0] D;
    and #(DELAY) and6 (D[0], in_delayed[2], in[1], in[0]);
    and #(DELAY) and7 (D[1], in_delayed[2], in[1], 1'b0);
    and #(DELAY) and8 (D[2], in_delayed[2], 1'b0, in[0]);
    and #(DELAY) and9 (D[3], in_delayed[1], in[0]);
    and #(DELAY) and10 (D[4], in_delayed[1], 1'b0);
    and #(DELAY) and11 (D[5], in[2], in[0]);
    and #(DELAY) and12 (D[6], in[2], in[1]);
    and #(DELAY) and13 (D[7], in[2], 1'b0);

    wire [7:0] out_delayed;
    or #(2*DELAY) or0 (out_delayed[0], D[0], D[1]);
    or #(2*DELAY) or1 (out_delayed[1], D[1], D[2]);
    or #(2*DELAY) or2 (out_delayed[2], D[2], D[3]);
    or #(2*DELAY) or3 (out_delayed[3], D[3], D[4]);
    or #(2*DELAY) or4 (out_delayed[4], D[4], D[5]);
    or #(2*DELAY) or5 (out_delayed[5], D[5], D[6]);
    or #(2*DELAY) or6 (out_delayed[6], D[6], D[7]);
    or #(2*DELAY) or7 (out_delayed[7], D[7]);

    assign #DELAY out = out_delayed;
endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out;

    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin : gen_block
            wire not_in2, not_in1, not_in0;
            wire and_nand, and_or;

            // Inverters for input bits using NAND gates
            nand(not_in2, in[2], in[2]);    // in[2] ~ N1
            nand(not_in1, in[1], in[1]);    // in[1] ~N2
            nand(not_in0, in[0], in[0]);    // in[0] ~N3

            // AND terms for each input combination
            and(and_nand, not_in2, not_in1, not_in0);
            and(out[i[2:0]], and_nand, enable);

            // Verify output selection with NAND (1ns delay)
            nand(and_or, out[i], out[i]);
        end
    endgenerate

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out;

