module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
;

reg [3:0] counter;
reg [7:0] bin;

// Binary counter logic
always @(posedge clk) begin
    if (rst) begin
        counter <= 4'd0;
    end else begin
        counter <= counter + 4'd1;
    end
end

// Binary to Gray conversion logic
always @(*) begin
    bin[7] = counter[3];
    bin[6] = counter[3] ^ counter[2];
    bin[5] = counter[3] ^ counter[2] ^ counter[1];
    bin[4] = counter[3] ^ counter[2] ^ counter[1] ^ counter[0];
    bin[3] = counter[2] ^ counter[1];
    bin[2] = counter[1];
    bin[1] = counter[0];
    bin[0] = 1'b0;
end

assign count = bin;

endmodule

