// Counter logic with asynchronous reset
always @(posedge clk) begin
    if (rst) begin
        counter <= 4'd0;
    end else begin
        counter <= counter + 4'd1;
    end
end

// Binary to Gray conversion (combinational)
always @(*) begin
    case (counter)
        4'h0: binary = 8'h00;
        4'h1: binary = 8'h01;
        4'h2: binary = 8'h03;
        4'h3: binary = 8'h05;
        4'h4: binary = 8'h07;
        4'h5: binary = 8'h09;
        4'h6: binary = 8'h0B;
        4'h7: binary = 8'h0D;
        4'h8: binary = 8'h0F;
        4'h9: binary = 8'h11;
        4'hA: binary = 8'h13;
        4'hB: binary = 8'h15;
        4'hC: binary = 8'h17;
        4'hD: binary = 8'h19;
        4'hE: binary = 8'h1B;
        4'hF: binary = 8'h1F;
        default: binary = 8'h00;
    endcase
end

