module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    reg [7:0] binary_reg;
    wire [7:0] binary_next;

    // Compute next binary value
    assign binary_next[7] = binary_reg[7];
    generate
        genvar i;
        for (i=6:0; i>=0; i=i-1) begin: binary_next_comp
            assign binary_next[i] = binary_reg[i] ^ binary_reg[i+1];
        end
    endgenerate
    assign binary_next[0] = 1'b0;

    // Update binary register on clock edge or reset
    always @(posedge clk) begin
        if (rst) begin
            binary_reg <= 8'd0;
        end else begin
            binary_reg <= binary_next;
        end
    end

    // Convert to Gray code
    assign count = binary_reg ^ (binary_reg >> 1);

endmodule

