  parameter [2:0] S0 = 3'd0,
                  S1 = 3'd1,
                  S2 = 3'd2,
                  S3 = 3'd3,
                  S4 = 3'd4,
                  S5 = 3'd5;

  reg [2:0] state_reg;

  // State transition logic
  always @(posedge clk) begin
    if (!resetn) begin
      state_reg <= S0;
    end else begin
      case (state_reg)
        S0: state_reg <= S1;
        S1: state_reg <= S2;
        S2: state_reg <= S3;
        S3: state_reg <= S4;
        S4: state_reg <= S5;
        S5: state_reg <= S0;
        default: state_reg <= S0;
      endcase
    end
  end

  // Output logic
  assign g = (state_reg == S0) ? 3'b001 :
             (state_reg == S1) ? 3'b010 :
             (state_reg == S2) ? 3'b011 :
             (state_reg == S3) ? 3'b100 :
             (state_reg == S4) ? 3'b101 :
             (state_reg == S5) ? 3'b110 :
             3'b001;

endmodule

