    S1 = 3'd1,
    S2 = 3'd2,
    S3 = 3'd3,
    S4 = 3'd4;

  reg [2:0] state, next_state;

  always @(*) begin
    case (state)
      S0: next_state = (r == 3'd0) ? S1 :
                      (r == 3'd1) ? S2 :
                      (r == 3'd2) ? S3 :
                      (r == 3'd3) ? S4 : S0;
      S1: next_state = (r == 3'd0) ? S2 :
                      (r == 3'd1) ? S3 :
                      (r == 3'd2) ? S4 : S1;
      S2: next_state = (r == 3'd0) ? S3 :
                      (r == 3'd1) ? S4 :
                      (r == 3'd2) ? S1 : S2;
      S3: next_state = (r == 3'd0) ? S4 :
                      (r == 3'd1) ? S2 :
                      (r == 3'd2) ? S3 : S3;
      S4: next_state = (r == 3'd0) ? S3 :
                      (r == 3'd1) ? S2 :
                      (r == 3'd2) ? S1 : S4;
      default: next_state = S0;
    endcase
  end

  always @(posedge clk) begin
    if (!resetn) begin
      state <= S0;
    end else begin
      state <= next_state;
    end
  end

  assign g = next_state;

endmodule

