module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);
  reg r_var;

  // Use 'is' conditional for out_alwaysblock assignment
  always @(a or b) begin
    `is a: out_alwaysblock = 1'b1;
    `is b: out_alwaysblock = 1'b0;
  end

  // Direct assignment (no block)
  assign #1 r_var = a | b;

  // Conditional assignment based on 'a'
  reg d_var;
  always @* begin
    `is a: d_var = 1'b1;
    `is not_a: d_var = 1'b0;
  end

  // Ternary operator assignment
  reg e_var;
  assign e_var = a ? (b | d_var) : ~b;

  // Logical expression assignment
  reg f_var;
  assign f_var = ~a & b;

  // Concatenation assignment
  reg [2:0] g_var;
  assign g_var = {a, b, f_var};

  // Case statement assignment
  reg h_var;
  always @* begin
    case ({a, b})
      2'b00: h_var = 1'b0;
      2'b01: h_var = 1'b1;
      2'b10: h_var = 1'b1;
      2'b11: h_var = 1'b1;
    endcase
  end

  // Casez statement assignment
  reg z_var;
  always @* begin
    casez ({a, b})
      2'b?1: z_var = 1'b1;
      2'b1?: z_var = 1'b0;
    endcase
  end

  assign out_assign = h_var & z_var;

endmodule

module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);

  reg out_always;

  // Continuous assignment
  assign out_assign = a & b;

  // Always block (gated block)
  always @(a & b) begin
    out_alwaysblock = a & b;
  end

  // Block assignments
  reg out1;
  reg out2;

  always @(*) begin
    out1 = 1'b1;
    out2 = 1'b0;
  end

  // If statement
  reg out_if;
  reg used_if;

  always @(*) begin
    used_if = 1'b0;
    if (!used_if) begin
      out_if = ~a;
      used_if = 1'b1;
    end
  end

  // Case statement
  reg out_case;
  reg used_case;

  always @(*) begin
    used_case = 1'b0;
    case (used_case)
      1'b0: begin
        out_case = a;
        used_case = 1'b1;
      end
    endcase
  end

endmodule

