  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [2:0] shift_reg;
  reg [2:0] next_shift_reg;

  always @* begin
    next_shift_reg = {shift_reg[1:0], S}; // Compute next shift value
    if (enable) begin
      // Update output with next_shift value
      Z = next_shift_reg[2];
      // Update shift register with next_shift value
      shift_reg = next_shift_reg;
    end
  end

  // Initialize shift register to 3'b000
  initial begin
    shift_reg = 3'b000;
  end

