module TopModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);

  reg [2:0] shift_reg;
  wire feedback;

  // Determine feedback based on S
  assign feedback = S ? {shift_reg[2], B} : {A, shift_reg[2:1]};

  // Update shift register on clock edge
  always @(posedge clk) begin
    if (enable) begin
      shift_reg <= {feedback, Z};
    end
  end

  // Update output Z based on enable and S
  always @(*) begin
    if (enable) begin
      if (S) begin
        Z = B;
      end else begin
        Z = C;
      end
    end else begin
      Z = shift_reg[2];
    end
  end

