module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  // State definitions
  localparam [2:0] s0 = 3'd0,
                   s1 = 3'd1,
                   s2 = 3'd2,
                   s3 = 3'd3,
                   s4 = 3'd4;

  reg [2:0] current_state, next_state;

  // Sequential state update
  always @(posedge clk) begin
    if (reset)
      current_state <= s0;
    else
      current_state <= next_state;
  end

  // Combinational next state logic
  always @(*) begin
    case (current_state)
      s0: next_state = w ? s1 : s0;
      s1: next_state = w ? s1 : s2;
      s2: next_state = w ? s3 : s4;
      s3: next_state = w ? s0 : s2;
      s4: next_state = w ? s1 : s2;
      default: next_state = s0;
    endcase
  end

  // Output logic
  assign z = (current_state == s4) || (current_state == s1);

endmodule

