module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  // Define the states using parameters
  localparam [2:0]
    s0 = 3'b000,
    s1 = 3'b001,
    s2 = 3'b010,
    s3 = 3'b011,
    s4 = 3'b100;

  reg [2:0] current_state, next_state;

  // State register (sequential logic)
  always @(posedge clk) begin
    if (reset)
      current_state <= s0;
    else
      current_state <= next_state;
  end

  // Next state logic (combinational)
  always @(*) begin
    case (current_state)
      s0: next_state = w ? s0 : s1;
      s1: next_state = w ? s2 : s1;
      s2: next_state = w ? s0 : s3;
      s3: next_state = w ? s4 : s3;
      s4: next_state = w ? s2 : s1;
      default: next_state = s0;
    endcase
  end

  // Output logic
  assign z = (current_state == s4);

endmodule

