module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  wire a1, b1;
  wire and1_out, and2_out;

  // Compute a1 and b1 using XOR with 1ns delay
  always @(a or b) begin
    if (a === || b === ) begin
      a1 = 1'bx;
      b1 = 1'bx;
    end else begin
      a1 = a ^ b;
      b1 = ~(a ^ b);
    end
  end

  // Compute AND and OR results with 2ns delay
  always @(a1 or b1) begin
    if (a1 === || b1 === ) begin
      {and1_out, and2_out} = 2'bx;
    end else begin
      #2;
      and1_out = a1 & b1;
      and2_out = a1 | b1;
    end
  end

  // Compute OR of the AND results with 2ns delay
  always @(and1_out or and2_out) begin
    if (and1_out === || and2_out === ) begin
      out = 1'bx;
    end else begin
      #2;
      out = and1_out | and2_out;
    end
  end

endmodule

