module TopModule (
  input a,
  input b,
  input c,
  input d,
  output reg out
);

  wire n1, n2, n3, n4, n5, n6, n7;

  always @* begin
    // First layer (a & b) with rise delay 10/15/20 and fall 5/10/15
    n1 = #(10:15:20, 5:10:15) a & b;
    // Second layer (c | d) with rise 20/25/30 and fall 10/15/20
    n2 = #(20:25:30, 10:15:20) c | d;
    // Third layer (NOT) with rise 5/10/15 and fall 10/15/20
    n3 = #(5:10:15, 10:15:20) ~n1;
    // Fourth layer (AND) with rise 15/20/25 and fall 5/10/15
    n4 = #(15:20:25, 5:10:15) n2 & n3;
    // Fifth layer (OR) with rise 10/15/20 and fall 20/25/30
    n5 = #(10:15:20, 20:25:30) n4 | n3;
    // Sixth layer (XOR) with rise 5/10/15 and fall 15/20/25
    n6 = #(5:10:15, 15:20:25) n5 ^ n2;
    // Seventh layer (NOR) with rise 20/25/30 and fall 5/10/15
    n7 = #(20:25:30, 5:10:15) ~n6;
    // Final output with rise 10/15/20 and fall 5/10/15
    out = #(10:15:20, 5:10:15) n7;
  end

endmodule

module TopModule (
