    else if (bump_left)
      next_dir = 1'b1; // Check bump_left if bump_right not high
    else
      next_dir = current_dir; // Default: retain current direction
  end

  // Sequential logic with asynchronous reset
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_dir <= 1'b0; // Initialize to right
    else
      current_dir <= next_dir;
  end

