module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg [1:0] current_state, next_state;
  localparam S0 = 2'd0,
             S1 = 2'd1,
             S2 = 2'd2,
             S3 = 2'd3,
             S4 = 2'd4;

  reg [1:0] next_state_next;

  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    next_state_next = current_state;
    if (ground) begin
      if (bump_left)
        next_state_next = S1;
      else if (bump_right)
        next_state_next = S2;
      else
        next_state_next = S0;
    end
    else begin
      case (current_state)
        S0: next_state_next = S0;
        S1: next_state_next = S3;
        S2: next_state_next = S4;
        S3: next_state_next = S0;
        S4: next_state_next = S0;
        default: next_state_next = S0;
      endcase
    end
  end

  always @(posedge clk or posedge areset) begin
    if (areset)
      next_state <= S0;
    else
      next_state <= next_state_next;
  end

  assign aaah = (current_state != S0);
  assign walk_left = (current_state == S1);
  assign walk_right = (current_state == S2);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // Define states
  localparam [1:0] aah_state = 2'b00,
                   walk_left_state = 2'b01,
                   walk_right_state = 2'b10;

  reg [1:0] current_state, next_state;

  // Sequential state transition
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= aah_state;
    end else begin
      current_state <= next_state;
    end
  end

  // Combinational next state logic
  reg [1:0] next_state;
  always @* begin
    case (current_state)
      aah_state: begin
        if (ground) begin
          if (bump_left) begin
            next_state = walk_left_state;
          end else if (bump_right) begin
            next_state = walk_right_state;
          end else begin
            next_state = aah_state;
          end
        end else begin
          next_state = aah_state;
        end
      end
      walk_left_state: begin
        next_state = ground ? walk_left_state : aah_state;
      end
      walk_right_state: begin
        next_state = ground ? walk_right_state : aah_state;
      end
      default: next_state = aah_state;
    endcase
  end

  // Output logic
  assign walk_left = (current_state == walk_left_state);
  assign walk_right = (current_state == walk_right_state);
  assign aaah = (current_state != aah_state);

endmodule

module TopModule (
  input clk,
