  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Combinational logic for next state
  always @(*) begin
    case (current_state)
      S0: next_state = ground ? S0 :
                     bump_left  ? S1 :
                     bump_right ? S2 : S3;
      S1: next_state = ground ? S0 :
                     bump_left  ? S1 :
                     bump_right ? S2 : S3;
      S2: next_state = ground ? S0 :
                     bump_left  ? S1 :
                     bump_right ? S2 : S3;
      S3: next_state = ground ? S0 :
                     bump_left  ? S1 :
                     bump_right ? S2 : S3;
      default: next_state = S0;
    endcase
  end

  // Output logic
  assign walk_left  = (current_state == S1);
  assign walk_right = (current_state == S2);
