module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  localparam [1:0] A  = 2'b00,
                   B  = 2'b01,
                   CH = 2'b10;

  reg [1:0] current_state, next_state;

  // State transition logic
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= A;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    next_state = current_state;
    case (current_state)
      A: begin
        if (ground) begin
          next_state = bump_right ? CH : B;
        end else begin
          if (bump_left) begin
            next_state = CH;
          end else if (bump_right) begin
            next_state = CH;
          end else begin
            next_state = A;
          end
        end
      end
      B: next_state = bump_right ? CH : B;
      CH: next_state = A;
      default: next_state = A;
    endcase
  end

  // Output assignments
  assign walk_left  = (current_state == CH);
  assign walk_right = (current_state == CH);
  assign aaah       = (current_state == A || current_state == B) ? 1'b1 : 1'b0;

endmodule

