      shift_reg <= 3'b0;
      start_shifting_reg <= 1'b0;
    end else begin
      shift_reg <= {shift_reg[1:0], data};
      if ({shift_reg[1:0], data} == 3'b111) begin
        start_shifting_reg <= 1'b1;
      end else if (start_shifting_reg && ( {shift_reg[1:0], data} != 3'b111 )) begin
