    if (reset) begin
      sync_0 <= 1'b0;
      sync_1 <= 1'b0;
      count <= 2'b0;
    end else begin
      // Synchronize the data signal to avoid metastability
      sync_0 <= data;
      sync_1 <= sync_0;

      // Update count based on synchronized data
      if (sync_1) begin
        count <= 2'd3;
      end else begin
        if (count != 2'd0) begin
          count <= count - 1'd1;
        end
      end
    end
  end

  // Output logic for start_shifting
  assign start_shifting = (reset) ? 1'b0 : (count != 2'd0);

