  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // Next state logic
  assign B3_next = d ? state[1] : 1'b0;
  assign S_next  = d ? (ack | state[2]) : 1'b0;
  assign S1_next = d ? state[3] : 1'b0;
  assign Count_next = d ? (ack | state[4]) : 1'b0;
  assign Wait_next = d ? (ack | state[5]) : 1'b0;

  // Output logic
  assign done = |state[7:0];
  assign counting = |state[6:0];
  assign shift_ena = |state[6:0] | |done;

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  localparam [9:0] 
    S0 = 10'b0000000001,
    S01 = 10'b0000000010,
    S011 = 10'b0000000100,
    S0110 = 10'b0000001000,
    S01101 = 10'b0000010000;

  // Combinational next state and control logic
  reg B3_next_comb;
  reg S_next_comb;
  reg S1_next_comb;
  reg Count_next_comb;
  reg Wait_next_comb;
  reg done_comb;
  reg counting_comb;
  reg shift_ena_comb;

  always @(*) begin
    // Default assignments
    B3_next_comb = 1'b0;
    S_next_comb = 1'b0;
    S1_next_comb = 1'b0;
    Count_next_comb = 1'b0;
    Wait_next_comb = 1'b0;
    done_comb = 1'b0;
    counting_comb = 1'b0;
    shift_ena_comb = 1'b0;

    if (ack) begin
      // Update control signals based on current state
      case (state)
        S0: begin
          B3_next_comb = d;
          S_next_comb = d;
          S1_next_comb = d;
        end
        S01: begin
          S_next_comb = 1'b1;
        end
        S011: begin
          S_next_comb = 1'b1;
        end
        S0110: begin
          S_next_comb = 1'b1;
        end
        S01101: begin
          Count_next_comb = 1'b1;
          done_comb = 1'b1;
        end
        default: ; // Other states use defaults
      endcase
    end
  end

  assign B3_next = B3_next_comb;
  assign S_next = S_next_comb;
  assign S1_next = S1_next_comb;
  assign Count_next = Count_next_comb;
  assign Wait_next = Wait_next_comb;
  assign done = done_comb;
  assign counting = counting_comb;
  assign shift_ena = shift_ena_comb;

endmodule

