             and a1 (p, A[j], B[j]);
             and a2 (g, A[j], carry[j-1]);
             xor x2 (C32, p, g);
             xor x3 (S[j+1], p, carry[j-1]);
             assign carry[j] = g;
         end
     endgenerate

     assign S[32] = carry[32];
