    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin : adder_stage
            wire a_modified, b_modified;
            assign a_modified = a[i] ^ ((i[0]) ? ~a[i] : 1'b0);
            assign b_modified = b[i] ^ ((i[0]) ? ~b[i] : 1'b0);
            assign sum[i] = a_modified ^ b_modified ^ carry[i];
