module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Generate intermediate comparison signals
    wire [3:0] greater;
    assign greater = (~A[3] & A[2] & A[1] & A[0]) | 
                    (~A[3] & (A[2] ^ A[1] ^ A[0])) | 
                    (A[3] & ~A[2] & A[1] & A[0]) | 
                    (A[3] & A[2] & ~A[1] & ~A[0]);

    // Invert the greater signal for A_less
    wire [3:0] not_greater;
    assign not_greater = ~greater;
    assign A_less = ~not_greater;

    // Generate equal and less-than signals
    wire [3:0] equal, less;

    assign equal[0] = (A[0] == B[0]);
    assign less[0]  = (~A[0] & B[0]);

    assign equal[1] = (A[1] == B[1]);
    assign less[1]  = (~A[1] & B[1]);

    assign equal[2] = (A[2] == B[2]);
    assign less[2]  = (~A[2] & B[2]);

    assign equal[3] = (A[3] == B[3]);

    // Combine equal bits to determine A_equal
    assign A_equal = &equal;

endmodule

module comparator_4bit(
