    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Invert the B bits for A_less calculations
    wire [3:0] B_xor = ~B;

    // Generate one-bit comparison signals using AND-OR operations
    assign A_greater = & (A & ~B_xor);  // All bits of A >= B
    assign A_equal  = (A == B);         // Bits are equal
    assign A_less   = | (A & B_xor);    // All bits of A < B

