module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
endmodule

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		// Reset outputs to default values
		rise <= 1'b0;
		down <= 1'b0;
		// Update previous input register with current a
		previous_a <= a;
	end
	else begin
		// Default assignments
		rise <= 1'b0;
		down <= 1'b0;
		// Priority to down detection
		if (a && !previous_a) begin
			down <= 1'b1;
		end
		else if (!a && previous_a) begin
			rise <= 1'b1;
		end
		// Update previous input register with current a
		previous_a <= a;
	end
end

endmodule

