module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

// Block 1: Register previous and current a values
reg a_prev, a_current;
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		a_prev <= 1'b0;
		a_current <= 1'b0;
	end else begin
		a_prev <= a;
		a_current <= a;
	end
end

// Block 2: Compute next rise and down
wire rise_next = a_prev & ~a_current;
wire down_next = ~a_prev & a_current;

// Block 3: Update outputs based on reset
always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		rise <= 1'b0;
		down <= 1'b0;
	end else begin
		rise <= rise_next;
		down <= down_next;
	end
end

