module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

localparam S0 = 2'b00,
           S1 = 2'b01,
           S2 = 2'b10,
           S3 = 2'b11;

reg [1:0] current_state, next_state;
reg [1:0] prev_data;

// State register and prev_data storage
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        current_state <= S0;
        prev_data <= 1'b0;
    end else begin
        current_state <= next_state;
        prev_data <= data_in;
    end
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: next_state = data_in ? S1 : S0;
        S1: next_state = data_in ? S1 : S2;
        S2: next_state = data_in ? S1 : S3;
        S3: next_state = data_in ? S1 : S0;
        default: next_state = S0;
    endcase
end

// Output logic
assign sequence_detected = (current_state == S3);

endmodule

module sequence_detector(
     input  clk, 
