     // Next state logic
     always @(*) begin
         case (current_state)
             sZero: 
                 next_state = data_in ? sOne : sZero;
             sOne: 
                 next_state = data_in ? sOne : sOneZero;
             sOneZero: 
                 next_state = data_in ? sOneZeroTwos : sZero;
             sOneZeroTwos: 
                 next_state = data_in ? sOne : sOneZeroTwosOne;
             sOneZeroTwosOne: 
                 next_state = data_in ? sOne : sOneZeroTwosOneOnes;
             sOneZeroTwosOneOnes: 
                 next_state = data_in ? sOne : sZero;
             default: 
